{
  "gate_token": "VISsSwhCsYQvL8vrbh-0Ug",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined city.",
      "visual_description": "A windswept ridge at dusk overlooking a shattered skyline of broken spires and torn banners; an ink-stained coat flaps as a brass compass spins.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of obvious traps below.",
      "visual_description": "An oil lamp held aloft, its single flame-eye narrowed, casting long warning shadows over a sketched city plan pinned by stones.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the approach to the castle gates.",
      "visual_description": "A small clockwork fox with blue glass eyes creeps along a cracked cobblestone road, key-wind tail ticking softly, looming iron gates ahead.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver slips in through a tall cathedral window.",
      "visual_description": "A figure in a clear diving helmet dives headfirst into stained glass as if it were water, coat shimmering with reflected broken city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team regroups beneath a row of tattered royal banners.",
      "visual_description": "A ruined courtyard hung with faded crimson banners; lamp glow, fox glints, and the cartographer's compass meet in a tight circle on broken tile.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "An armored patrol marches past their hiding spot.",
      "visual_description": "From behind a toppled fountain, blue glass eyes and a single flame-eye peek as plated boots clank down a moonlit avenue.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The sleeping tax collector blocks the records office door.",
      "visual_description": "A rotund official slumped against an iron-bound door, ledger book under his cheek as a pillow, stamped papers fluttering from his sleeves.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "Mara lifts a key ring without waking him.",
      "visual_description": "Ink-stained fingers gingerly pluck a brass key from a snoring belt loop while the oracle lamp dims its eye to keep quiet.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "A cursed tower hums with bad magic.",
      "visual_description": "A leaning black tower pulses with violet veins of light; the cartographer marks a wide detour while the fox bristles, ears twitching.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Rumors of a great winged beast roll across the rooftops.",
      "visual_description": "Distant smoke curls into a shape too large to name; the oracle lamp's eye contracts to a slit, refusing to confirm or deny.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "Frightened townsfolk are coaxed back indoors.",
      "visual_description": "Lantern light spills from a doorway as gentle hands wave shadowy figures inside; the glass diver gestures softly, helmet fogged with rain.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door demands a true name.",
      "visual_description": "A silver door set in moss-grown stone bears a single sigil shaped like an eye; the lamp lifts to meet it, flame-eye to carved eye.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Inside, the captive is found behind cracked mirrors.",
      "visual_description": "A hall of fractured mirrors; the glass diver swims through a tall pane and reaches for a thin hand reflected a hundred times over.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Tin Fox triggers an alarm to buy them time.",
      "visual_description": "The clockwork fox darts across a marble floor, tail whirring, knocking a brass bell that booms through a vaulted throne room.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "A patrol storms the wrong wing while the team flees.",
      "visual_description": "Wide split-panel view: armored boots thunder left through smoke; right, the cartographer, lamp, and diver sprint down a colonnade.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The sleeping tax collector unknowingly waves them through a checkpoint.",
      "visual_description": "Still half-asleep, the official stamps a blank page mid-snore as the rescue party tiptoes past his lantern-lit booth.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They race for the river bridge as the city burns behind them.",
      "visual_description": "A long stone bridge over black water; silhouettes run beneath embers, coat reflecting flame, compass swinging wildly, lamp held high.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "Across the bridge, Mara marks the ruined city as 'closed'.",
      "visual_description": "Dawn over a misty far shore; an ink-stained hand draws a careful X on a folded map while the fox curls at her boots and the lamp dozes.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp", "glass_diver"]
    }
  ]
}

